with recent_departments as (select * from departments where location != 'New York' and budget >= 2213000), agg as (select case when budget >= 4370000 then 'high' when budget >= 1724000 then 'mid' else 'low' end budget_bucket, round(avg(budget), 2) avg_budget, max(budget) - min(budget) budget_range from recent_departments group by case when budget >= 4370000 then 'high' when budget >= 1724000 then 'mid' else 'low' end) select budget_bucket, avg_budget, budget_range from agg order by avg_budget
